const housingSourceOverrides={"Kommunal hyresgaranti":"https://www.boverket.se/sv/kommunernas-bostadsforsorjning/kommunens-verktyg/hyresgarantier/","SÄBO – särskilt boende för äldre":"https://termbank.socialstyrelsen.se/article.php?tid=750","Vård- och omsorgsboende (VoB)":"https://termbank.socialstyrelsen.se/article.php?tid=750","Socialt kontrakt":"https://www.boverket.se/sv/kommunernas-bostadsforsorjning/","Trygghetsboende":"https://www.lulea.se/omsorg--stod/aldre-och-seniorer/boende-for-aldre/trygghetsboenden-och-seniorboenden.html","Seniorboende 55+/65+":"https://www.lulea.se/omsorg--stod/aldre-och-seniorer/boende-for-aldre/trygghetsboenden-och-seniorboenden.html"};
const housingTopicSources={"Sociala kontrakt":"https://www.boverket.se/sv/kommunernas-bostadsforsorjning/","Akuta boenden":"https://www.socialstyrelsen.se/","Skydd och vård":"https://www.socialstyrelsen.se/","Tillfälliga boenden":"https://www.boverket.se/sv/kommunernas-bostadsforsorjning/","Boende med stöd":"https://www.socialstyrelsen.se/","Äldreboenden":"https://termbank.socialstyrelsen.se/article.php?tid=750","Funktionsnedsättning":"https://www.socialstyrelsen.se/","Bostadssociala begrepp":"https://www.boverket.se/sv/kommunernas-bostadsforsorjning/","Bostadsmarknad och planering":"https://www.boverket.se/sv/kommunernas-bostadsforsorjning/","Studentbostäder":"https://www.boverket.se/sv/","Ungdomsbostäder":"https://www.boverket.se/sv/","Markägande och småhus":"https://www.lantmateriet.se/sv/","Ombyggnad":"https://www.boverket.se/sv/PBL-kunskapsbanken/","Gemensamma och kooperativa boenden":"https://www.boverket.se/sv/samhallsplanering/bostadsmarknad/upplatelseformer/bygg-bogemenskaper/","Små och kompakta bostäder":"https://www.boverket.se/sv/PBL-kunskapsbanken/","Kommunens bostadspolitiska verktyg":"https://www.boverket.se/sv/kommunernas-bostadsforsorjning/","Boende för nyanlända":"https://www.boverket.se/sv/kommunernas-bostadsforsorjning/","Krisboenden och inkvartering":"https://www.mcf.se/","Arbetskrafts- och entreprenörsboenden":"https://www.boverket.se/sv/PBL-kunskapsbanken/"};
function setupHousingReference(){
 const categories=[...new Set(housingTerms.map(r=>r[1]))].sort((a,b)=>a.localeCompare(b,'sv'));
 const choose=q('housing-term-category');categories.forEach(cat=>{const o=element('option',cat);o.value=cat;choose.append(o)});
 const render=()=>{const term=q('housing-term-search').value.toLocaleLowerCase('sv-SE').trim(),category=choose.value,body=q('housing-terms');body.replaceChildren();const rows=housingTerms.filter(r=>(!category||r[1]===category)&&(!term||r.join(' ').toLocaleLowerCase('sv-SE').includes(term)));rows.forEach(r=>{const tr=element('tr');r.forEach((v,i)=>{const td=element('td');if(i===3){const pattern=/https?:\/\/[^\s;,]+/i;const match=v.match(pattern);if(match){const url=match[0].replace(/[.)]+$/,'');const prefix=v.slice(0,match.index);const preceding=prefix.replace(/(?:^|\s)(?:Källa|[A-ZÅÄÖ][\p{L} .-]{1,60}):\s*$/u,'').trim();const trailing=v.slice(match.index+url.length).replace(/^[.)]+/,'').trim();if(preceding)td.append(document.createTextNode(preceding+' '));const a=element('a','Läs mer');a.href=url;a.target='_blank';a.rel='noopener noreferrer';td.append(a);if(trailing)td.append(document.createTextNode(' '+trailing));}else{td.textContent=v;const url=housingSourceOverrides[r[0]]||housingTopicSources[r[1]];if(url){td.append(document.createTextNode(' '));const link=element('a','Läs mer');link.href=url;link.target='_blank';link.rel='noopener noreferrer';link.title='Allmän vägledning inom området – inte nödvändigtvis en definition av begreppet';td.append(link);}}}else td.textContent=v;tr.append(td)});body.append(tr)});q('housing-term-count').textContent=rows.length+' av '+housingTerms.length+' begrepp';};
 q('housing-term-search').addEventListener('input',render);choose.addEventListener('change',render);render();
 const laws=q('housing-laws');housingLaws.forEach(([title,number,description,url])=>{const section=element('section');section.className='definition';section.append(element('h3',title+' ('+number+')'));const p=element('p',description);p.append(document.createTextNode(' '));const a=element('a','Läs mer');a.href=url;a.target='_blank';a.rel='noopener noreferrer';p.append(a);section.append(p);laws.append(section)});
}
setupHousingReference();function renderIndicators(){const term=q('search').value.trim().toLocaleLowerCase('sv-SE'),topic=q('topic').value;const rows=content.indicators.filter(r=>(!topic||r.topic===topic)&&(!term||(r.name+' '+r.definition+' '+r.provider).toLocaleLowerCase('sv-SE').includes(term)));const tbody=q('indicators');tbody.replaceChildren();rows.forEach(r=>{const tr=element('tr');[r.name,r.unit,'Ej inläst',r.provider,'s. '+r.pages+' (kontroll pågår)'].forEach(t=>tr.append(element('td',t)));tbody.append(tr)});q('indicator-count').textContent=rows.length+' av '+content.indicators.length+' nyckeltal visas.'}function renderMeasures(){const selected=q('measure-goal').value,term=q('measure-search').value.trim().toLocaleLowerCase('sv-SE'),list=q('measures');list.replaceChildren();const rows=content.measures.filter(m=>(!selected||m.goalId===selected)&&(!term||(m.name+' '+m.description+' '+m.responsible).toLocaleLowerCase('sv-SE').includes(term)));q('measure-count').textContent=rows.length+' av '+content.measures.length+' insatser';content.policyGoals.forEach(g=>{const matched=rows.filter(m=>m.goalId===g.id);if(!matched.length)return;const section=element('section');section.className='definition';section.append(element('h3',g.title));matched.forEach(m=>{const item=element('article');item.className='definition';item.append(element('h4',m.name),element('p',m.description),element('p','Ansvarig: '+m.responsible));const a=element('a','Programmet, s. '+m.page+' ↗');a.href=content.source+'#page='+(Math.floor(m.page/2)+1);a.target='_blank';a.rel='noopener';item.append(a);section.append(item)});list.append(section)})}
async function init(){try{const r=await fetch('data/content.json');if(!r.ok)throw Error('Kunde inte läsa innehållsfilen.');content=await r.json();const topics=[...new Set(content.indicators.map(r=>r.topic))].sort((a,b)=>a.localeCompare(b,'sv'));topics.forEach(t=>{const opt=element('option',t);opt.value=t;q('topic').append(opt)});q('search').addEventListener('input',renderIndicators);q('topic').addEventListener('change',renderIndicators);renderIndicators();const goals=q('goals');content.policyGoals.forEach(g=>{const card=element('article');card.className='goal';card.append(element('h3',g.title),element('p',g.summary));const n=content.measures.filter(m=>m.goalId===g.id).length;const a=element('a','Visa '+n+' kopplade insatser →');a.href='#insatser';a.addEventListener('click',()=>{q('measure-goal').value=g.id;renderMeasures()});card.append(a);const src=element('p');const l=element('a','Programmet, s. '+g.page+' ↗');l.href=content.source+'#page='+(Math.floor(g.page/2)+1);l.target='_blank';l.rel='noopener';src.append(l);card.append(src);goals.append(card)});const mg=q('measure-goal');content.policyGoals.forEach(g=>{const o=element('option',g.title);o.value=g.id;mg.append(o)});mg.addEventListener('change',renderMeasures);q('measure-search').addEventListener('input',renderMeasures);renderMeasures();const defs=q('definitions');content.indicators.forEach(r=>{const box=element('section');box.className='definition';box.append(element('h3',r.id+'. '+r.name),element('p',r.definition),element('small','Föreslagen enhet: '+r.unit+' · Källa: '+r.provider+' · Rapport: s. '+r.pages+' (preliminärt)'));defs.append(box)})}catch(e){q('indicator-count').textContent='Kunde inte ladda nyckeltal: '+e.message;q('definitions').textContent='Innehållet kunde inte laddas.'}}init();